import json, pathlib, subprocess, urllib.request
repo=pathlib.Path(r"E:\WebAIBridge")
def run(args, timeout=8):
    p=subprocess.run(args,cwd=str(repo),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout)
    return {"code":p.returncode,"out":p.stdout.decode(errors="replace").strip(),"err":p.stderr.decode(errors="replace").strip()}
head=run(["git.exe","-C",str(repo),"rev-parse","HEAD"])
status=run(["git.exe","-C",str(repo),"status","--porcelain"])
cut=repo/"app"/"data"/"projects-live-control-plane-cutover-r42.json"
cut_state=None
if cut.exists():
    try: cut_state=json.loads(cut.read_text(encoding="utf-8-sig"))
    except Exception as exc: cut_state={"parseError":str(exc)}
health_path=pathlib.Path(r"E:\pc-github-relay\.pc-relay\health.json")
health=json.loads(health_path.read_text(encoding="utf-8-sig")) if health_path.exists() else {}
api_ok=False
try:
    with urllib.request.urlopen("http://127.0.0.1:17448/api/status",timeout=3) as resp:
        body=json.load(resp)
    api_ok=True
except Exception:
    body={}
print(json.dumps({
    "head":head["out"],
    "gitStatus":status["out"].splitlines(),
    "cutoverExists":cut.exists(),
    "cutoverStatus":None if cut_state is None else cut_state.get("status"),
    "holdActive":None if cut_state is None else cut_state.get("holdActive"),
    "bridgeApiOk":api_ok,
    "relayReconciliationRequired":bool(health.get("reconciliation_required",False)),
    "relayLastError":health.get("last_error"),
},ensure_ascii=True))
